    same(nextOauthStep('resource'), 'done')
  })
  check('隐式流程（responseType=token）被标记为问题', () => {
    const p = validateAuthorize({ responseType: 'token', state: 's', pkce: true })
    same(p, ['response-type'])
  })
  check('缺 state 与 PKCE 都被列出，顺序固定', () => {
