  // 熵 = 长度 × log2(字符集大小)：假设每字符独立均匀随机
  const bits = Math.round(length * Math.log2(alphabet) * 100) / 100
  let grade = 'weak'
  if (bits >= 128) grade = 'strong'
  else if (bits >= 80) grade = 'ok'
  return { bits, grade }
}

